struct BINKAUDIODECOMP
{
    short* pOverlap;
    unsigned int uFrameLength;
    float fRoot;
    unsigned int uFrameBytes;
    unsigned int uOverlapBytes;
    unsigned int uOverlapShift;
    unsigned int uChannels;
    int bFirstBlock;
    unsigned int uBandCount;
    unsigned int uReserved;
    unsigned int uFlags;
    unsigned int uStateBytes;
    unsigned int uBands[26];
};

