#ifdef __ghs__
static inline unsigned int BinkLoadLE32(const unsigned char* pSource)
{
    int iValue;
    __lwbrx(pSource, iValue);
    return (unsigned int)iValue;
}

static inline short BinkLoadLE16(const short* pSource)
{
    short iValue;
    __lhbrx(pSource, iValue);
    return iValue;
}

static inline void BinkStoreLE16(short* pDestination, int iValue)
{
    __sthbrx(pDestination, iValue);
}
#else
static inline unsigned int BinkLoadLE32(const unsigned char* pSource)
{
    return (unsigned int)pSource[0] | ((unsigned int)pSource[1] << 8) | ((unsigned int)pSource[2] << 16)
           | ((unsigned int)pSource[3] << 24);
}

static inline short BinkLoadLE16(const short* pSource)
{
    const unsigned char* pBytes = (const unsigned char*)pSource;
    return (short)(pBytes[0] | (pBytes[1] << 8));
}

static inline void BinkStoreLE16(short* pDestination, int iValue)
{
    unsigned char* pBytes = (unsigned char*)pDestination;
    pBytes[0] = (unsigned char)iValue;
    pBytes[1] = (unsigned char)(iValue >> 8);
}
#endif

