extern "C" double fxptof(unsigned int uValue)
{
    float fMantissa = (float)(int)((uValue & ~FXPT_SIGN_BIT) >> FXPT_MANTISSA_SHIFT);
    double dResult = fMantissa * FXPT_SCALE_TABLE[uValue & FXPT_SCALE_MASK];

    if ((uValue & FXPT_SIGN_BIT) != 0)
    {
        dResult = -dResult;
    }

    return dResult;
}

static inline void BinkStoreSample(short* pDestination, float fSample, double dScale)
{
    int iSample = (int)((double)fSample * dScale);

    if (iSample >= BINKAUDIO_SAMPLE_MAX)
    {
        iSample = BINKAUDIO_SAMPLE_MAX;
    }
    else if (iSample <= BINKAUDIO_SAMPLE_MIN)
    {
        iSample = BINKAUDIO_SAMPLE_MIN;
    }

    BinkStoreLE16(pDestination, iSample);
}

extern "C" void ClampToS16_c(double dScale, short* pOutput, const float* pInput, unsigned int uCount)
{
    unsigned int uIndex;

    for (uIndex = 0; uIndex < uCount; ++uIndex)
    {
        BinkStoreSample(&pOutput[uIndex], pInput[uIndex], dScale);
    }
}

extern "C" void CrossFade(short* pOutput, const short* pOverlap, unsigned int uBytes, unsigned int uShift)
{
    unsigned int uCount = uBytes >> 1;
    unsigned int uIndex;
    int iOld;
    int iNew;

    for (uIndex = 0; uIndex < uCount; ++uIndex)
    {
        iOld = BinkLoadLE16(&pOverlap[uIndex]);
        iNew = BinkLoadLE16(&pOutput[uIndex]);
        BinkStoreLE16(&pOutput[uIndex], (((unsigned int)((iNew - iOld) * (int)uIndex)) >> uShift) + iOld);
    }
}

extern "C" unsigned int BinkAudioDecompressMemoryLE(unsigned int uSampleRate, unsigned int uChannels,
                                                    unsigned int uFlags)
{
    unsigned int uFrameLength;

    if (uSampleRate >= BINKAUDIO_SAMPLE_RATE_LONG)
    {
        return (((BINKAUDIO_FRAME_LONG * uChannels * 2) >> BINKAUDIO_OVERLAP_DIVISOR_SHIFT)
                + BINKAUDIO_STATE_HEADER_BYTES + BINKAUDIO_STATE_ALIGNMENT_ROUNDING)
               & ~BINKAUDIO_STATE_ALIGNMENT_ROUNDING;
    }

    uFrameLength = BINKAUDIO_FRAME_SHORT;
    if (uSampleRate >= BINKAUDIO_SAMPLE_RATE_MEDIUM)
    {
        uFrameLength = BINKAUDIO_FRAME_MEDIUM;
    }

    return (((uFrameLength * uChannels * 2) >> BINKAUDIO_OVERLAP_DIVISOR_SHIFT) + BINKAUDIO_STATE_HEADER_BYTES
            + BINKAUDIO_STATE_ALIGNMENT_ROUNDING)
           & ~BINKAUDIO_STATE_ALIGNMENT_ROUNDING;
}

extern "C" BINKAUDIODECOMP* BinkAudioDecompressOpenLE(void* pMemory, unsigned int uSampleRate, unsigned int uChannels,
                                                      unsigned int uFlags)
{
    BINKAUDIODECOMP* pState = static_cast<BINKAUDIODECOMP*>(pMemory);
    unsigned int uFrameLength;
    unsigned int uFrameSamples;
    unsigned int uFrameBytes;
    unsigned int uTransformChannels;
    unsigned int uHalfRate;
    unsigned int uHalfFrame;
    unsigned int uBandCount;
    unsigned int uBand;
    unsigned int uLevel;
    unsigned int uBandStart;

    if (uSampleRate < BINKAUDIO_SAMPLE_RATE_LONG)
    {
        uFrameLength = BINKAUDIO_FRAME_SHORT;
        if (uSampleRate >= BINKAUDIO_SAMPLE_RATE_MEDIUM)
        {
            uFrameLength = BINKAUDIO_FRAME_MEDIUM;
        }

        uFrameSamples = uFrameLength * uChannels;
        uFrameBytes = uFrameSamples * 2;
    }
    else
    {
        uFrameLength = BINKAUDIO_FRAME_LONG;
        uFrameSamples = uChannels * BINKAUDIO_FRAME_LONG;
        uFrameBytes = uFrameSamples * 2;
    }

    uTransformChannels = uChannels;
    if ((uFlags & BINKAUDIO_FLAG_DCT) == 0)
    {
        uTransformChannels = 1;
        uSampleRate = uSampleRate * uChannels;
        uFrameLength = uFrameSamples;
        if (uFrameSamples > BINKAUDIO_FRAME_LONG)
        {
            return NULL;
        }
    }

    uHalfRate = (uSampleRate + 1) >> 1;
    uHalfFrame = uFrameLength >> 1;

    for (uBandCount = 0; uBandCount < BINKAUDIO_BAND_FREQUENCY_COUNT; ++uBandCount)
    {
        if (uHalfRate <= BINKAUDIO_BAND_FREQUENCIES[uBandCount])
        {
            break;
        }
    }

    memset(pState, 0, sizeof(BINKAUDIODECOMP));
    pState->uStateBytes = (uFrameBytes >> BINKAUDIO_OVERLAP_DIVISOR_SHIFT) + BINKAUDIO_STATE_HEADER_BYTES;
    pState->pOverlap = reinterpret_cast<short*>(static_cast<unsigned char*>(pMemory) + BINKAUDIO_STATE_HEADER_BYTES);
    radfft_init();

    if (uTransformChannels == 1)
    {
        uFlags = uFlags & ~BINKAUDIO_FLAG_PLANAR;
    }

    pState->uFlags = uFlags;
    pState->uChannels = uTransformChannels;
    pState->uBandCount = uBandCount;
    pState->uFrameLength = uFrameLength;
    pState->uFrameBytes = uFrameBytes;
    pState->uOverlapBytes = uFrameBytes >> BINKAUDIO_OVERLAP_DIVISOR_SHIFT;
    pState->uOverlapShift = 0;

    uLevel = uFrameBytes >> 5;
    if (uLevel == BINKAUDIO_OVERLAP_LEVEL_32)
    {
        pState->uOverlapShift = 5;
    }
    else if (uLevel == BINKAUDIO_OVERLAP_LEVEL_64)
    {
        pState->uOverlapShift = 6;
    }
    else if (uLevel == BINKAUDIO_OVERLAP_LEVEL_128)
    {
        pState->uOverlapShift = 7;
    }
    else if (uLevel == BINKAUDIO_OVERLAP_LEVEL_256)
    {
        pState->uOverlapShift = 8;
    }

    pState->fRoot = BINKAUDIO_ROOT_NUMERATOR / sqrtf((float)uFrameLength);

    for (uBand = 0; uBand < uBandCount; ++uBand)
    {
        uBandStart = (BINKAUDIO_BAND_FREQUENCIES[uBand] * uHalfFrame) / uHalfRate;
        if (uBandStart == 0)
        {
            uBandStart = 1;
        }

        pState->uBands[uBand] = uBandStart;
    }

    pState->uBands[uBandCount] = uHalfFrame;
    pState->bFirstBlock = 1;
    return pState;
}

struct BinkBitReader
{
    const unsigned char* pCursor;
    const unsigned char* pLimit;
    unsigned int uBuffer;
    unsigned int uBitCount;
};

static bool BinkReadBits(BinkBitReader& reader, unsigned int uBits, unsigned int uMask, unsigned int& uValue)
{
    unsigned int uWord;

    if (reader.uBitCount < uBits)
    {
        if (reader.pCursor >= reader.pLimit)
        {
            return false;
        }

        uWord = BinkLoadLE32(reader.pCursor);
        reader.pCursor += 4;
        uValue = reader.uBuffer | (uWord << reader.uBitCount);
        reader.uBuffer = uWord >> (uBits - reader.uBitCount);
        reader.uBitCount = reader.uBitCount + 32 - uBits;
    }
    else
    {
        uValue = reader.uBuffer;
        reader.uBuffer = reader.uBuffer >> uBits;
        reader.uBitCount = reader.uBitCount - uBits;
    }

    uValue = uValue & uMask;
    return true;
}

static bool BinkReadBits(BinkBitReader& reader, unsigned int uBits, unsigned int& uValue)
{
    return BinkReadBits(reader, uBits, (1u << uBits) - 1, uValue);
}

static bool BinkReadChannel(BinkBitReader& reader, const BINKAUDIODECOMP* pState, float* afCoefficients)
{
    float afSignScale[2];
    float afQuant[BINKAUDIO_MAX_BANDS + 1];
    const unsigned int* pBand;
    const float* pQuant;
    float* pCoefficient;
    float* pSegmentEnd;
    float fQuant;
    unsigned int uFrameLength = pState->uFrameLength;
    unsigned int uBandCount = pState->uBandCount;
    unsigned int uValue;
    unsigned int uBit;
    unsigned int uIndex;
    unsigned int uRunEnd;
    unsigned int uWidth;
    unsigned int uMask;
    unsigned int uBandEnd;
    unsigned int uCoefficient;
    unsigned int uSignBits;
    unsigned int uBand;

    memset(afCoefficients, 0, uFrameLength * sizeof(float));

    if (!BinkReadBits(reader, BINKAUDIO_FLOAT_BITS, uValue))
    {
        return false;
    }

    afCoefficients[0] = (float)fxptof(uValue);
    if (!BinkReadBits(reader, BINKAUDIO_FLOAT_BITS, uValue))
    {
        return false;
    }

    afCoefficients[1] = (float)fxptof(uValue);
    afQuant[0] = 0.0f;

    for (uBand = 0; uBand < uBandCount; ++uBand)
    {
        if (!BinkReadBits(reader, BINKAUDIO_QUANT_BITS, uValue))
        {
            return false;
        }

        if (uValue > BINKAUDIO_QUANT_LIMIT)
        {
            uValue = BINKAUDIO_QUANT_LIMIT;
        }

        afQuant[1 + uBand] = BINKAUDIO_QUANT_TABLE[uValue];
    }

    if (uFrameLength > BINKAUDIO_START_COEFFICIENT)
    {
        uIndex = BINKAUDIO_START_COEFFICIENT;
        pBand = pState->uBands;
        pQuant = afQuant;
        pCoefficient = afCoefficients + uIndex;

        do
        {
            if (!BinkReadBits(reader, BINKAUDIO_RLE_FLAG_BITS, uBit))
            {
                return false;
            }

            if (uBit == 0)
            {
                uRunEnd = uIndex + BINKAUDIO_RUN_UNIT;
            }
            else
            {
                if (!BinkReadBits(reader, BINKAUDIO_RLE_INDEX_BITS, uValue))
                {
                    return false;
                }

                uRunEnd = uIndex + BINKAUDIO_RLE_LENGTHS[uValue] * BINKAUDIO_RUN_UNIT;
            }

            if (uRunEnd > uFrameLength)
            {
                uRunEnd = uFrameLength;
            }

            if (!BinkReadBits(reader, BINKAUDIO_WIDTH_BITS, uWidth))
            {
                return false;
            }

            if (uWidth == 0)
            {
                uIndex = uRunEnd;
                pCoefficient = afCoefficients + uIndex;
                continue;
            }

            uMask = (1u << uWidth) - 1;
            while (uIndex < uRunEnd)
            {
                uBandEnd = *pBand * 2;
                if (uBandEnd <= uIndex)
                {
                    do
                    {
                        ++pBand;
                        ++pQuant;
                    } while (*pBand * 2 <= uIndex);

                    uBandEnd = *pBand * 2;
                }

                fQuant = *pQuant;
                uIndex = uBandEnd;
                if (uRunEnd < uBandEnd)
                {
                    uIndex = uRunEnd;
                }

                afSignScale[0] = fQuant;
                afSignScale[1] = -fQuant;
                pSegmentEnd = afCoefficients + uIndex;

                while (pCoefficient < pSegmentEnd)
                {
                    if (!BinkReadBits(reader, uWidth, uMask, uCoefficient))
                    {
                        return false;
                    }

                    if (reader.uBitCount == 0 && uCoefficient != 0)
                    {
                        if (reader.pCursor >= reader.pLimit)
                        {
                            return false;
                        }

                        reader.uBuffer = BinkLoadLE32(reader.pCursor);
                        reader.pCursor += 4;
                        reader.uBitCount = 32;
                    }

                    *pCoefficient = (float)(int)uCoefficient * afSignScale[reader.uBuffer & 1];
                    uSignBits = uCoefficient != 0;
                    reader.uBitCount = reader.uBitCount - uSignBits;
                    reader.uBuffer = reader.uBuffer >> uSignBits;
                    ++pCoefficient;
                }
            }
        } while (uRunEnd < uFrameLength);
    }

    return true;
}

static unsigned int BinkApplySkip(const BINKAUDIODECOMP* pState, short* pDestination, int* piSkipSamples,
                                  unsigned int uOutputBytes)
{
    unsigned int uSkipBytes;

    if (piSkipSamples != NULL && *piSkipSamples != 0)
    {
        uSkipBytes = *piSkipSamples << pState->uChannels;
        if (uOutputBytes <= uSkipBytes)
        {
            *piSkipSamples = *piSkipSamples - (int)(uOutputBytes >> pState->uChannels);
            uOutputBytes = 0;
        }
        else
        {
            uSkipBytes = uSkipBytes & BINKAUDIO_SKIP_ALIGNMENT_MASK;
            uOutputBytes = uOutputBytes - uSkipBytes;
            if (uOutputBytes != 0)
            {
                memmove(pDestination, reinterpret_cast<unsigned char*>(pDestination) + uSkipBytes, uOutputBytes);
            }

            *piSkipSamples = 0;
        }
    }

    return uOutputBytes;
}

extern "C" void BinkAudioDecompressLE(BINKAUDIODECOMP* pState, void* pOutput, unsigned int* puOutputBytes,
                                      const void* pInput, const void** ppInputEnd, const void* pInputLimit,
                                      float* pWork, int* piSkipSamples)
{
    float afCoefficients[BINKAUDIO_FRAME_LONG];
    BinkBitReader reader;
    const unsigned char* pStart = static_cast<const unsigned char*>(pInput);
    short* pDestination = static_cast<short*>(pOutput);
    short* pTarget = pDestination;
    short* pOverlap = pState->pOverlap;
    float* pChannel = pWork;
    double dRoot = (double)pState->fRoot;
    unsigned int uFrameLength = pState->uFrameLength;
    unsigned int uFlags = pState->uFlags;
    unsigned int uChannels = pState->uChannels;
    unsigned int uOverlapBytes = pState->uOverlapBytes;
    unsigned int uFade = 0;
    unsigned int uConsumed = 0;
    unsigned int uOutputBytes;
    unsigned int uSkipBytes;
    unsigned int uSample;
    unsigned int uChannelsLeft;
    const float* pLeft;
    const float* pRight;

    reader.pCursor = pStart;
    reader.pLimit = static_cast<const unsigned char*>(pInputLimit);
    reader.uBuffer = 0;
    reader.uBitCount = 0;

    if (pState->bFirstBlock == 0)
    {
        uFade = pState->uOverlapShift;
    }

    if ((uFlags & BINKAUDIO_FLAG_DCT) == 0 || reader.pCursor < reader.pLimit)
    {
        if ((uFlags & BINKAUDIO_FLAG_DCT) != 0)
        {
            reader.uBuffer = BinkLoadLE32(reader.pCursor) >> BINKAUDIO_HEADER_BITS;
            reader.pCursor += 4;
            reader.uBitCount = 32 - BINKAUDIO_HEADER_BITS;
        }

        uChannelsLeft = uChannels;
        if (uChannelsLeft != 0)
        {
            do
            {
                if (!BinkReadChannel(reader, pState, afCoefficients))
                {
                    memset(pChannel, 0, uFrameLength * sizeof(float));
                }
                else if ((uFlags & BINKAUDIO_FLAG_DCT) != 0)
                {
                    radfft_idct(pChannel, afCoefficients, uFrameLength);
                }

                pChannel += uFrameLength;
                uChannelsLeft = uChannelsLeft - 1;
            } while (uChannelsLeft != 0);
        }

        if ((uFlags & BINKAUDIO_FLAG_PLANAR) == 0)
        {
            if (uChannels == 1)
            {
                ClampToS16_c(dRoot, pTarget, pWork, uFrameLength);
            }
            else
            {
                pLeft = pWork;
                pRight = pWork + uFrameLength;
                for (uSample = 0; uSample < uFrameLength; ++uSample)
                {
                    BinkStoreSample(&pTarget[2 * uSample], pLeft[uSample], dRoot);
                    BinkStoreSample(&pTarget[2 * uSample + 1], pRight[uSample], dRoot);
                }
            }

            if (uFade != 0)
            {
                CrossFade(pTarget, pOverlap, uOverlapBytes, uFade);
            }

            if (uOverlapBytes != 0)
            {
                memmove(pOverlap,
                        reinterpret_cast<unsigned char*>(pTarget) + (uChannels * uFrameLength * 2 - uOverlapBytes),
                        uOverlapBytes);
            }
        }
        else
        {
            uOverlapBytes = uOverlapBytes >> 1;
            ClampToS16_c(dRoot, pTarget, pWork, uFrameLength);
            if (uFade != 0)
            {
                uFade = uFade - 1;
                CrossFade(pTarget, pOverlap, uOverlapBytes, uFade);
            }

            uSkipBytes = uFrameLength * 2 - uOverlapBytes;
            pTarget = reinterpret_cast<short*>(reinterpret_cast<unsigned char*>(pTarget) + uSkipBytes);
            if (uOverlapBytes != 0)
            {
                memmove(pOverlap, pTarget, uOverlapBytes);
            }

            pOverlap = reinterpret_cast<short*>(reinterpret_cast<unsigned char*>(pOverlap) + uOverlapBytes);
            ClampToS16_c(dRoot, pTarget, pWork + uFrameLength, uFrameLength);
            if (uFade != 0)
            {
                CrossFade(pTarget, pOverlap, uOverlapBytes, uFade);
            }

            if (uOverlapBytes != 0)
            {
                memmove(pOverlap, reinterpret_cast<unsigned char*>(pTarget) + uSkipBytes, uOverlapBytes);
            }
        }

        uConsumed = (unsigned int)(reader.pCursor - pStart) & BINKAUDIO_BYTE_COUNT_MASK;
    }

    pState->bFirstBlock = 0;
    uOutputBytes = pState->uFrameBytes - pState->uOverlapBytes;

    uOutputBytes = BinkApplySkip(pState, pDestination, piSkipSamples, uOutputBytes);
    if (puOutputBytes != NULL)
    {
        *puOutputBytes = uOutputBytes;
    }

    if (ppInputEnd != NULL)
    {
        *ppInputEnd = pStart + uConsumed;
    }
}

void scalar_ripre(rfft_complex* pData, unsigned int uCount, unsigned int uTwiddleBase)
{
    unsigned int uIndex;
    rfft_complex* pLow;
    rfft_complex* pHigh;
    float fDifference;
    float fSum;
    float fRotatedRe;
    float fRotatedIm;
    float fLowRe;
    float fLowIm;
    float fTwiddleRe;
    float fTwiddleIm;

    if (uCount < 2)
    {
        return;
    }

    for (uIndex = 1; uIndex < uCount; ++uIndex)
    {
        pLow = &pData[uIndex];
        pHigh = &pData[2 * uTwiddleBase - uIndex];
        fTwiddleRe = RFFT_TWIDDLES[uTwiddleBase + uIndex].re;
        fTwiddleIm = RFFT_TWIDDLES[uTwiddleBase + uIndex].im;
        fDifference = RFFT_HALF * (pLow->re - pHigh->re);
        fSum = RFFT_HALF * (pLow->im + pHigh->im);
        fRotatedRe = fTwiddleRe * fSum + fTwiddleIm * fDifference;
        fRotatedIm = fTwiddleRe * fDifference - fTwiddleIm * fSum;
        fLowIm = pLow->im - fSum;
        fLowRe = pLow->re - fDifference;
        pLow->im = fLowIm + fRotatedIm;
        pLow->re = fLowRe - fRotatedRe;
        pHigh->re = fLowRe + fRotatedRe;
        pHigh->im = fRotatedIm - fLowIm;
    }
}

void scalar_cfpass(rfft_complex* pData, const PlanElement* pPlan, unsigned int uCount)
{
    const PlanElement* pElement = pPlan;
    unsigned int uLast;
    unsigned int uQuarter;
    unsigned int uIndex;
    rfft_complex* pFirst;
    rfft_complex* pSecond;
    rfft_complex* pThird;
    rfft_complex* pFourth;
    float fFirstSumRe;
    float fFirstSumIm;
    float fDifferenceIm;
    float fThirdRe;
    float fSecondRe;
    float fSecondIm;
    float fRotatedRe;
    float fRotatedIm;
    float fConjugateRe;
    float fConjugateIm;
    float fTwiddleRe;
    float fTwiddleIm;
    float fSumRe;
    float fSumIm;
    float fLowRe;
    float fLowIm;

    do
    {
        uQuarter = pElement->uCount;
        pFirst = pData + pElement->uOffset;
        pSecond = pFirst + uQuarter;
        pThird = pSecond + uQuarter;
        pFourth = pThird + uQuarter;

        fSecondRe = pThird->re;
        fThirdRe = pFourth->re;
        fFirstSumRe = fSecondRe + fThirdRe;
        fFirstSumIm = pThird->im + pFourth->im;
        fSecondIm = pFirst->im;
        fDifferenceIm = pThird->im - pFourth->im;
        fSumRe = pFirst->re;
        pThird->im = fSecondIm - fFirstSumIm;
        pThird->re = fSumRe - fFirstSumRe;
        pFirst->re = fSumRe + fFirstSumRe;
        fThirdRe = fThirdRe - fSecondRe;
        pFirst->im = fSecondIm + fFirstSumIm;
        fSecondIm = pSecond->im;
        fSumRe = pSecond->re;
        pFourth->im = fSecondIm - fThirdRe;
        pFourth->re = fSumRe - fDifferenceIm;
        pSecond->re = fSumRe + fDifferenceIm;
        pSecond->im = fSecondIm + fThirdRe;

        for (uIndex = 1; uIndex < uQuarter; ++uIndex)
        {
            fTwiddleRe = RFFT_TWIDDLES[uQuarter + uIndex].re;
            fTwiddleIm = RFFT_TWIDDLES[uQuarter + uIndex].im;
            pFirst = pData + pElement->uOffset + uIndex;
            pSecond = pFirst + uQuarter;
            pThird = pSecond + uQuarter;
            pFourth = pThird + uQuarter;

            fRotatedRe = fTwiddleRe * pThird->re - fTwiddleIm * pThird->im;
            fRotatedIm = fTwiddleRe * pThird->im + fTwiddleIm * pThird->re;
            fConjugateRe = fTwiddleRe * pFourth->re + fTwiddleIm * pFourth->im;
            fConjugateIm = fTwiddleRe * pFourth->im - fTwiddleIm * pFourth->re;
            fSumRe = fRotatedRe + fConjugateRe;
            fSumIm = fRotatedIm + fConjugateIm;
            fLowRe = pFirst->re;
            fLowIm = pFirst->im;
            pThird->re = fLowRe - fSumRe;
            pThird->im = fLowIm - fSumIm;
            pFirst->re = fLowRe + fSumRe;
            pFirst->im = fLowIm + fSumIm;
            fRotatedIm = fRotatedIm - fConjugateIm;
            fConjugateRe = fConjugateRe - fRotatedRe;
            fLowRe = pSecond->re;
            fLowIm = pSecond->im;
            pFourth->re = fLowRe - fRotatedIm;
            pFourth->im = fLowIm - fConjugateRe;
            pSecond->im = fLowIm + fConjugateRe;
            pSecond->re = fLowRe + fRotatedIm;
        }

        uLast = pElement->uCount;
        ++pElement;
    } while (uLast < uCount);
}

void scalar_radix4(rfft_complex* pOutput, const rfft_complex* pFirst, const rfft_complex* pSecond,
                   const rfft_complex* pThird, const rfft_complex* pFourth, unsigned int uStart, unsigned int uEnd,
                   const unsigned short* pOrder)
{
    unsigned int uIndex;
    rfft_complex* pDestination;
    float fSecondDifferenceRe;
    float fSecondDifferenceIm;
    float fSecondSumRe;
    float fSecondSumIm;
    float fFirstDifferenceRe;
    float fFirstDifferenceIm;
    float fFirstSumRe;
    float fFirstSumIm;

    for (uIndex = uStart; uIndex < uEnd; ++uIndex)
    {
        fSecondDifferenceIm = pSecond[uIndex].im - pFourth[uIndex].im;
        fSecondSumRe = pSecond[uIndex].re + pFourth[uIndex].re;
        fSecondSumIm = pSecond[uIndex].im + pFourth[uIndex].im;
        fSecondDifferenceRe = pFourth[uIndex].re - pSecond[uIndex].re;
        fFirstDifferenceIm = pFirst[uIndex].im - pThird[uIndex].im;
        fFirstSumRe = pFirst[uIndex].re + pThird[uIndex].re;
        fFirstSumIm = pFirst[uIndex].im + pThird[uIndex].im;
        fFirstDifferenceRe = pFirst[uIndex].re - pThird[uIndex].re;
        pDestination = pOutput + pOrder[uIndex];
        pDestination[0].re = fFirstSumRe + fSecondSumRe;
        pDestination[2].im = fFirstSumIm - fSecondSumIm;
        pDestination[2].re = fFirstSumRe - fSecondSumRe;
        pDestination[0].im = fFirstSumIm + fSecondSumIm;
        pDestination[1].re = fFirstDifferenceRe + fSecondDifferenceIm;
        pDestination[1].im = fFirstDifferenceIm + fSecondDifferenceRe;
        pDestination[3].re = fFirstDifferenceRe - fSecondDifferenceIm;
        pDestination[3].im = fFirstDifferenceIm - fSecondDifferenceRe;
    }
}

void scalar_2radix2(rfft_complex* pOutput, const rfft_complex* pFirst, const rfft_complex* pSecond,
                    const rfft_complex* pThird, const rfft_complex* pFourth, unsigned int uStart, unsigned int uEnd,
                    const unsigned short* pOrder)
{
    unsigned int uIndex;
    rfft_complex* pDestination;

    for (uIndex = uStart; uIndex < uEnd; ++uIndex)
    {
        pDestination = pOutput + pOrder[uIndex];
        pDestination[0].re = pFirst[uIndex].re + pThird[uIndex].re;
        pDestination[0].im = pFirst[uIndex].im + pThird[uIndex].im;
        pDestination[1].re = pFirst[uIndex].re - pThird[uIndex].re;
        pDestination[1].im = pFirst[uIndex].im - pThird[uIndex].im;
        pDestination[2].re = pSecond[uIndex].re + pFourth[uIndex].re;
        pDestination[2].im = pSecond[uIndex].im + pFourth[uIndex].im;
        pDestination[3].re = pFourth[uIndex].re - pSecond[uIndex].re;
        pDestination[3].im = pFourth[uIndex].im - pSecond[uIndex].im;
    }
}

void scalar_dct_merge(float* pOutput, const float* pInput, unsigned int uCount)
{
    unsigned int uHalf = uCount >> 1;
    unsigned int uIndex;
    const float* pEnd = pInput + uCount;

    for (uIndex = 0; uIndex < uHalf; ++uIndex)
    {
        float fFirst = *pInput++;
        float fSecond = *--pEnd;
        *pOutput++ = fFirst;
        *pOutput++ = fSecond;
    }
}

void scalar_dct3_modulate(float* pOutput, const float* pInput, unsigned int uCount, unsigned int uHalfCount,
                          const rfft_complex* pTwiddles)
{
    unsigned int uIndex;
    float fTwiddleRe;
    float fTwiddleIm;
    float fLow;
    float fHigh;

    pOutput[0] = pInput[0] + pInput[0];
    pOutput[1] = RFFT_SQRT2 * pInput[uCount >> 1];

    for (uIndex = 1; uIndex < uHalfCount; ++uIndex)
    {
        fTwiddleRe = pTwiddles[uIndex].re;
        fTwiddleIm = pTwiddles[uIndex].im;
        fLow = pInput[uIndex];
        fHigh = pInput[uCount - uIndex];
        pOutput[2 * uIndex] = fTwiddleRe * fLow - fTwiddleIm * fHigh;
        pOutput[2 * uIndex + 1] = fTwiddleRe * fHigh + fTwiddleIm * fLow;
    }
}

void fft_driver(rfft_complex* pData, unsigned int uCount, RFFT_PASS_CALLBACK pPass)
{
    unsigned int uQuarter = uCount >> 2;
    const PlanElement* pPlan = RFFT_PLAN;
    PlanElement plan;

    if (uCount > RFFT_PLAN_THRESHOLD)
    {
        plan.uOffset = 0;
        plan.uCount = (unsigned short)uQuarter;
        pPlan = &plan;
        fft_driver(pData, uQuarter * 2, pPass);
        fft_driver(pData + uQuarter * 2, uQuarter, pPass);
        fft_driver(pData + uQuarter * 3, uQuarter, pPass);
    }

    pPass(pData, pPlan, uQuarter);
}

int is_pow2(unsigned int uValue)
{
    return uValue != 0 && (uValue & (uValue - 1)) == 0;
}

extern "C" void radfft_init()
{
    static int bInitialised = 0;

    if (bInitialised != 0)
    {
        return;
    }

    bInitialised = 1;
}

extern "C" void radfft_cfft(float* pOutput, const float* pInput, unsigned int uCount)
{
    rfft_complex* pResult = reinterpret_cast<rfft_complex*>(pOutput);
    const rfft_complex* pFirst = reinterpret_cast<const rfft_complex*>(pInput);
    unsigned int uQuarter;
    unsigned int uSplit;
    unsigned int uRemainder;
    const unsigned short* pOrder;

    if (!is_pow2(uCount) || uCount > RFFT_MAX_COUNT)
    {
        __builtin_trap();
    }

    if (uCount <= 2)
    {
        if (uCount == 2)
        {
            float fFirstRe = pFirst[0].re;
            float fFirstIm = pFirst[0].im;
            float fSecondRe = pFirst[1].re;
            float fSecondIm = pFirst[1].im;
            pResult[0].re = fFirstRe + fSecondRe;
            pResult[0].im = fFirstIm + fSecondIm;
            pResult[1].re = fFirstRe - fSecondRe;
            pResult[1].im = fFirstIm - fSecondIm;
        }
        else if (uCount == 1)
        {
            pResult[0] = pFirst[0];
        }

        return;
    }

    uQuarter = uCount >> 2;
    uSplit = uQuarter / 3 + 1;
    uRemainder = uQuarter - uSplit + 1;
    pOrder = RFFT_ORDER + uQuarter;
    void (*radix4)(rfft_complex*, const rfft_complex*, const rfft_complex*, const rfft_complex*, const rfft_complex*,
                   unsigned int, unsigned int, const unsigned short*) = scalar_radix4;
    const rfft_complex* pSecond = pFirst + uQuarter;
    const rfft_complex* pThird = pFirst + uQuarter * 2;
    const rfft_complex* pFourth = pFirst + uQuarter * 3;
    radix4(pResult, pFirst, pSecond, pThird, pFourth, 0, uSplit, pOrder);
    scalar_2radix2(pResult, pFirst, pSecond, pThird, pFourth, uSplit, uRemainder, pOrder);
    radix4(pResult, pFourth, pFirst, pSecond, pThird, uRemainder, uQuarter, pOrder);

    if (uCount >= 8)
    {
        fft_driver(pResult, uCount, scalar_cfpass);
    }
}

extern "C" void radfft_rifft(float* pOutput, float* pInput, unsigned int uCount)
{
    float fSum;
    float fDifference;
    unsigned int uQuarter;

    if (!is_pow2(uCount) || uCount - 2 >= RFFT_MAX_COUNT - 1)
    {
        __builtin_trap();
    }

    fSum = RFFT_HALF * (pInput[0] + pInput[1]);
    fDifference = RFFT_HALF * (pInput[0] - pInput[1]);
    pInput[1] = fDifference;
    pInput[0] = fSum;

    uQuarter = uCount >> 2;
    if (uQuarter != 0)
    {
        scalar_ripre(reinterpret_cast<rfft_complex*>(pInput), uQuarter, uQuarter);
    }

    radfft_cfft(pOutput, pInput, uCount >> 1);
}

extern "C" void radfft_idct(float* pOutput, float* pInput, unsigned int uCount)
{
    if (!is_pow2(uCount) || uCount - 2 >= RFFT_MAX_COUNT - 1)
    {
        __builtin_trap();
    }

    if (uCount * 4 <= RFFT_MAX_COUNT)
    {
        scalar_dct3_modulate(pOutput, pInput, uCount, uCount >> 1, RFFT_TWIDDLES + uCount);
    }
    else
    {
        scalar_dct3_modulate(pOutput, pInput, uCount, uCount >> 1,
                             RFFT_TWIDDLES + RFFT_LARGE_TWIDDLE_BASE + (uCount >> 1));
    }

    radfft_rifft(pInput, pOutput, uCount);
    scalar_dct_merge(pOutput, pInput, uCount);
}
